6	@@ -0,0 +1,62 @@
7	+import React from 'react';
8	+import type { Meta, StoryObj } from '@storybook/react-webpack5';
9	+import { expect, userEvent, within } from 'storybook/test';
10	+import { ZimmAccordion } from './index';
11	+
12	+const meta: Meta<typeof ZimmAccordion> = {
13	+  title: 'Elements/ZimmAccordion',
14	+  component: ZimmAccordion,
15	+};
16	+export default meta;
17	+type Story = StoryObj<typeof ZimmAccordion>;
18	+
19	+// Deliberately generic labels — the SFCC-847 filter labels (Category / Colour / Size /
20	+// Material / Sleeve Length / Availability) belong on the ZimmFiltersDrawerContent stories,
21	+// not this atom's. This story asserts the primitive's contract in isolation.
22	+const SAMPLE_ITEMS = [
23	+  { id: 'alpha', label: 'Alpha', content: <p>Alpha content.</p> },
24	+  { id: 'beta', label: 'Beta', content: <p>Beta content.</p> },
25	+  { id: 'gamma', label: 'Gamma', content: <p>Gamma content.</p> },
26	+];
27	+
28	+export const Default: Story = {
29	+  args: { items: SAMPLE_ITEMS },
30	+};
31	+
32	+export const WithDefaultExpanded: Story = {
33	+  args: { items: SAMPLE_ITEMS, defaultExpandedId: 'alpha' },
34	+};
35	+
36	+export const ClickTogglesExpansion: Story = {
37	+  args: { items: SAMPLE_ITEMS },
38	+  play: async ({ canvasElement }) => {
39	+    const canvas = within(canvasElement);
40	+    const alphaHeader = canvas.getByRole('button', { name: /alpha/i });
41	+    await expect(alphaHeader).toHaveAttribute('aria-expanded', 'false');
42	+    await userEvent.click(alphaHeader);
43	+    await expect(alphaHeader).toHaveAttribute('aria-expanded', 'true');
44	+    // Clicking the same header again collapses it (Chakra's `allowToggle` behaviour, which
45	+    // SFCC-847 does not contradict — the AC's "one expanded at a time" rule doesn't require
46	+    // that at least one is always open).
47	+    await userEvent.click(alphaHeader);
48	+    await expect(alphaHeader).toHaveAttribute('aria-expanded', 'false');
49	+  },
50	+};
51	+
52	+// AC covered: "expanding a new accordion collapses the previously expanded one." Asserted
53	+// via aria-expanded rather than a visible/hidden panel query — the underlying `AccordionPanel`
54	+// mounts unconditionally and Chakra hides it via CSS, so a panel presence assertion would
55	+// pass either way. aria-expanded is the actual behavioural contract for assistive tech.
56	+export const OnlyOneExpandedAtATime: Story = {
57	+  args: { items: SAMPLE_ITEMS, defaultExpandedId: 'alpha' },
58	+  play: async ({ canvasElement }) => {
59	+    const canvas = within(canvasElement);
60	+    const alphaHeader = canvas.getByRole('button', { name: /alpha/i });
61	+    const betaHeader = canvas.getByRole('button', { name: /beta/i });
62	+    await expect(alphaHeader).toHaveAttribute('aria-expanded', 'true');
63	+    await expect(betaHeader).toHaveAttribute('aria-expanded', 'false');
64	+    await userEvent.click(betaHeader);
65	+    await expect(alphaHeader).toHaveAttribute('aria-expanded', 'false');
66	+    await expect(betaHeader).toHaveAttribute('aria-expanded', 'true');
67	+  },
68	+};
