103	+  test('opens the item matching defaultExpandedId on first render', () => {
104	+    render(<ZimmAccordion items={SAMPLE_ITEMS} defaultExpandedId="beta" />);
105	+    expect(screen.getByRole('button', { name: /alpha/i })).toHaveAttribute('aria-expanded', 'false');
