117	+  test('unknown defaultExpandedId does not crash and leaves all items collapsed', () => {
118	+    render(<ZimmAccordion items={SAMPLE_ITEMS} defaultExpandedId="nonexistent" />);
119	+    expect(screen.getByRole('button', { name: /alpha/i })).toHaveAttribute('aria-expanded', 'false');
