128	@@ -0,0 +1,98 @@
129	+import React from 'react';
130	+import {
131	+  Accordion,
132	+  AccordionItem,
133	+  AccordionButton,
134	+  AccordionPanel,
135	+  chakra,
136	+  useMultiStyleConfig,
137	+} from '@chakra-ui/react';
138	+import { ChevronDownIcon, ChevronUpIcon } from 'app/components/icons';
139	+
140	+const ZIMM_ACCORDION_RECIPE = 'ZimmAccordion';
141	+
142	+export type ZimmAccordionItem = {
143	+  /** Stable identifier — matches `defaultExpandedId` and acts as the React key. */
144	+  id: string;
145	+  /**
146	+   * Group label shown in the header. Rendered uppercase via the `textStyle="productNames"`
147	+   * design-system entry (see typography.ts), so callers pass Title Case ("Colour", not
148	+   * "COLOUR") — this keeps i18n content faithful.
149	+   */
150	+  label: string;
151	+  /**
152	+   * Facet UI rendered inside the panel when expanded. SFCC-847 stops at the group
153	+   * container — the real facet content (radio buttons, colour swatches, size chips, etc.)
154	+   * is SFCC-108's scope.
155	+   */
156	+  content: React.ReactNode;
157	+  /**
158	+   * Optional content rendered directly under the header only when the item is collapsed —
159	+   * use for a compact summary the shopper needs to see at a glance without expanding the
160	+   * accordion (e.g. the current selection chips for a filter facet). Hidden when the item
161	+   * is expanded so the full content in `content` takes over. Rendered outside Chakra's
162	+   * AccordionPanel, so it does not participate in the expand/collapse animation.
163	+   * Leave undefined for accordions with no summary.
164	+   */
165	+  alwaysVisibleContent?: React.ReactNode;
166	+};
167	+
168	+type ZimmAccordionProps = {
169	+  items: readonly ZimmAccordionItem[];
170	+  /**
171	+   * Which item is open on first render. Uncontrolled — the user can toggle from here on
172	+   * without informing the parent.
173	+   */
174	+  defaultExpandedId?: string;
175	+};
176	+
177	+/**
178	+ * Single-open accordion group — a Zimmermann-styled wrapper around Chakra's Accordion
179	+ * primitive. Delivers SFCC-847's accordion behaviour: only one item expanded at a time
180	+ * (matches AC #5 and the DS 2026 Figma audited 2026-09-16, node
181	+ * wPiWmZZOVKnrENUWk2XWWm/40003890:151742 which shows exactly one accordion expanded),
182	+ * expanding a new item collapses the previously expanded one, and each header exposes
183	+ * `aria-expanded` reflecting its state (unchanged from Chakra's own `AccordionButton`).
184	+ *
185	+ * The chevron swaps ChevronDown (collapsed) ↔ ChevronUp (expanded) using the render-prop
186	+ * form of `AccordionItem`. A CSS-only 180° rotation on a single glyph could animate
187	+ * between them, but Zimmermann's own chevron pair (icons/zimm.tsx nodes 40002082:49961 and
188	+ * 40002128:29217) are drawn as distinct shapes — swapping is faithful, rotating isn't.
189	+ *
190	+ * @param props see ZimmAccordionProps
191	+ */
192	+export const ZimmAccordion = ({ items, defaultExpandedId }: ZimmAccordionProps) => {
193	+  const styles = useMultiStyleConfig(ZIMM_ACCORDION_RECIPE, {});
194	+  // `findIndex` returns -1 when the id isn't in `items`. Chakra's `defaultIndex={-1}` logs a
195	+  // "out of range" warning at dev-time; coercing to `undefined` instead falls back to
196	+  // Chakra's own default (nothing expanded).
197	+  const initialIndex = items.findIndex((item) => item.id === defaultExpandedId);
198	+  const defaultIndex = initialIndex >= 0 ? initialIndex : undefined;
199	+
200	+  return (
201	+    <Accordion allowToggle defaultIndex={defaultIndex} sx={styles.root}>
202	+      {items.map((item) => (
203	+        <AccordionItem key={item.id} sx={styles.item}>
204	+          {({ isExpanded }) => (
205	+            <>
206	+              <AccordionButton sx={styles.header}>
207	+                <chakra.span textStyle="productNames" sx={styles.label}>
208	+                  {item.label}
209	+                </chakra.span>
210	+                {isExpanded ? (
211	+                  <ChevronUpIcon boxSize="var(--zimm-icon-size-xl)" />
212	+                ) : (
213	+                  <ChevronDownIcon boxSize="var(--zimm-icon-size-xl)" />
214	+                )}
215	+              </AccordionButton>
216	+              {!isExpanded && item.alwaysVisibleContent && (
217	+                <chakra.div sx={styles.alwaysVisible}>{item.alwaysVisibleContent}</chakra.div>
218	+              )}
219	+              <AccordionPanel sx={styles.panel}>{item.content}</AccordionPanel>
220	+            </>
221	+          )}
222	+        </AccordionItem>
223	+      ))}
224	+    </Accordion>
225	+  );
226	+};
