232	@@ -0,0 +1,74 @@
233	+// SFCC-847 drawer/content/filters — accordion recipe. Tokens sourced from the Zimmermann
234	+// Design System 2026 Figma (node wPiWmZZOVKnrENUWk2XWWm/40003890:151736 and /40003890:151742,
235	+// audited 2026-09-16). Divider colour resolves to `alias/color/border/secondary` in Figma
236	+// which binds to `#dddddd` — surfaced in this codebase as
237	+// `--zimm-color-border-tertiary` (see foundation/colour.ts `border.tertiary`). Figma's N+1
238	+// divider pattern (7 dividers for 6 accordions: top + between + bottom) is reproduced by
239	+// giving each item both `borderTop` and `borderBottom`, with no `_first`/`_last` override.
240	+
241	+export const ZimmAccordion = {
242	+  parts: ['root', 'item', 'header', 'label', 'alwaysVisible', 'panel'],
243	+  baseStyle: {
244	+    root: {
245	+      width: '100%',
246	+    },
247	+    // Every item carries both top and bottom borders so the accordion group reads as N+1
248	+    // dividers between headers, matching Figma. Chakra's own AccordionItem defaults are
249	+    // overridden here rather than layered on: the default `1px solid` uses the theme border
250	+    // colour, not the drawer-specific tertiary token.
251	+    item: {
252	+      borderTop: 'var(--zimm-border-width-default) solid var(--zimm-color-border-tertiary)',
253	+      borderBottom: 'var(--zimm-border-width-default) solid var(--zimm-color-border-tertiary)',
254	+      // Collapse the shared edge between adjacent items so a single 1px line renders instead
255	+      // of a doubled 2px seam. Only the last item keeps its own borderBottom.
256	+      _notLast: {
257	+        borderBottom: 'none',
258	+      },
259	+    },
260	+    // Chakra's AccordionButton is a real <button>; these sx overrides layer over its defaults
261	+    // (transparent bg, blackAlpha _hover, block layout). Cursor: pointer stays Chakra-owned.
262	+    // paddingBlock 20px per row yields ~41px between adjacent header baselines (20 + 1px
263	+    // border + 20), matching Figma's `Accordion group` gap-with-divider rhythm.
264	+    header: {
265	+      display: 'flex',
266	+      alignItems: 'center',
267	+      justifyContent: 'space-between',
268	+      width: '100%',
269	+      paddingBlock: 'var(--zimm-scale-l)',
270	+      paddingInline: 0,
271	+      _hover: {
272	+        backgroundColor: 'transparent',
273	+      },
274	+      _focusVisible: {
275	+        // audit-allow: 2px matches Chakra's default focus-ring outline width; no dedicated
276	+        // Zimmermann token for outline width (only offset + composite).
277	+        outline: '2px solid var(--zimm-color-border-focus)',
278	+        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
279	+      },
280	+    },
281	+    label: {
282	+      // textTransform intentionally NOT set here — `textStyle="productNames"` (applied in
283	+      // index.tsx) already carries `textTransform: 'uppercase'` from the design system.
284	+      color: 'var(--zimm-color-text-default)',
285	+      flex: '1 0 0',
286	+      textAlign: 'left',
287	+    },
288	+    // Rendered directly below the header regardless of expanded state. Padding matches the
289	+    // panel's so a facet's chips align visually with the options list below when expanded.
290	+    alwaysVisible: {
291	+      paddingBlock: 'var(--zimm-scale-s)',
292	+      paddingInline: 0,
293	+    },
294	+    panel: {
295	+      paddingBlock: 'var(--zimm-scale-s)',
296	+      paddingInline: 0,
297	+      // Constrain children to available width. Without this, Stack/Flex children can expand
298	+      // beyond the drawer's bounds, causing horizontal overflow (audited 2026-09-16: Stack
299	+      // was 634px on 375px viewport). Width 100% + border-box ensures children don't exceed
300	+      // their parent's computed width.
301	+      width: '100%',
302	+      boxSizing: 'border-box',
303	+      overflow: 'hidden',
304	+    },
305	+  },
306	+};
