1624	+import React from 'react';
1625	+import { Box, SimpleGrid, Stack, Text } from '@chakra-ui/react';
1626	+import { useIntl } from 'react-intl';
1627	+import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
1628	+import { ADD_FILTER, REMOVE_FILTER } from 'app/utils/refinementValues';
1629	+import type { ShopperSearchTypes } from 'commerce-sdk-isomorphic';
1630	+
1631	+type ZimmSizeFilterProps = {
1632	+  filter: { attributeId: string; values?: ShopperSearchTypes.ProductSearchRefinementValue[] };
1633	+  toggleFilter: (value: { value: string | number }, attributeId: string, selected: boolean) => void;
1634	+  selectedFilters: readonly string[];
1635	+};
1636	+
1637	+/** One flat grid of size chips using the OOTB fixed 44px column width. */
1638	+const SizeChipRow = ({ filter, toggleFilter, selectedFilters }: ZimmSizeFilterProps) => {
1639	+  const intl = useIntl();
1640	+
1641	+  return (
1642	+    <SimpleGrid columns={4} spacing="var(--zimm-scale-2xs)" marginTop="var(--zimm-scale-2xs)">
1643	+      {filter.values?.map((value) => {
1644	+        const isSelected = selectedFilters.some((filterValue) => filterValue == value.value);
1645	+        if (value.hitCount === 0 && !isSelected) return null;
1646	+
1647	+        return (
1648	+          <ZimmButton
1649	+            key={String(value.value)}
1650	+            variant={isSelected ? 'primary' : 'secondary'}
1651	+            size="medium"
1652	+            label={value.label}
1653	+            ariaLabel={intl.formatMessage(isSelected ? REMOVE_FILTER : ADD_FILTER, { label: value.label })}
1654	+            role="checkbox"
1655	+            ariaChecked={isSelected}
1656	+            onClick={() => toggleFilter(value, filter.attributeId, isSelected)}
1657	+            sx={{
1658	+              ...(isSelected
1659	+                ? {}
1660	+                : {
1661	+                    borderColor: 'var(--zimm-color-border-secondary)',
1662	+                    _hover: { borderColor: 'var(--zimm-color-border-secondary)' },
1663	+                  }),
1664	+            }}
1665	+          />
1666	+        );
1667	+      })}
1668	+    </SimpleGrid>
1669	+  );
1670	+};
1671	+
1672	+/**
1673	+ * SFCC-847 — the Size facet's chip row, plus sub-group headings (e.g. Clothing/Accessories/
1674	+ * Shoes) when SFCC returns c_size as nested groups — the same nesting
1675	+ * `flattenRefinementValues` (overrides/app/utils/refinementValues.ts) already anticipates. A
1676	+ * flat (ungrouped) c_size refinement renders as a single ungrouped row.
1677	+ *
1678	+ * Grouping depends entirely on the shape SFCC sends: the API currently returns c_size flat, so
1679	+ * the ungrouped branch is what renders today. Producing the grouped design is BM configuration
1680	+ * (nested parent values), not a front-end change.
1681	+ *
1682	+ * @param props see ZimmSizeFilterProps
1683	+ */
1684	+export const ZimmSizeFilter = ({ filter, toggleFilter, selectedFilters }: ZimmSizeFilterProps) => {
1685	+  const groups = filter.values ?? [];
1686	+  const isNested = groups.some((group) => group.values && group.values.length > 0);
1687	+
1688	+  if (!isNested) {
1689	+    return <SizeChipRow filter={filter} toggleFilter={toggleFilter} selectedFilters={selectedFilters} />;
1690	+  }
1691	+
1692	+  return (
1693	+    <Stack sx={{ gap: 'var(--zimm-scale-m)' }}>
1694	+      {groups.map((group) => (
1695	+        <Box key={String(group.value)}>
1696	+          {/* Sub-group heading (Clothing / Accessories / Shoes). `textStyle="body2Strong"`
1697	+              matches the design system's 14/18 medium letterSpacing entry; the earlier
1698	+              `fontStyle="italic"` was speculative and had no Figma reference (audited
1699	+              2026-09-16). */}
1700	+          <Text textStyle="body2Strong" marginBottom="var(--zimm-scale-xs)">
1701	+            {group.label}
1702	+          </Text>
1703	+          <SizeChipRow
1704	+            filter={{ attributeId: filter.attributeId, values: group.values }}
1705	+            toggleFilter={toggleFilter}
1706	+            selectedFilters={selectedFilters}
1707	+          />
1708	+        </Box>
1709	+      ))}
1710	+    </Stack>
1711	+  );
1712	+};
