3903	+
3904	+export type PendingRefinements = Record<string, string[]>;
3905	+
3906	+type UseFilterDrawerStateParams = {
3907	+  /** Whether the filter drawer is currently open — pending state resyncs from the
3908	+   *  currently-applied filters every time this transitions to true. */
3909	+  isOpen: boolean;
3910	+  /**
3911	+   * The category ID currently reflected in the URL — used as the initial pending
3912	+   * category selection each time the drawer opens. Pass `params.categoryId` for a
3913	+   * standard single-category page, or `undefined` when no sub-category is active.
3914	+   */
3915	+  categoryId?: string;
3916	+  /** The currently-applied refinements — pass searchParams.refine (the real URL-derived
3917	+   *  ground truth), NOT productSearchResult.selectedRefinements (the SFCC API field that
3918	+   *  only reflects what the backend chose to echo back, which is often incomplete).
3919	+   *  Values may be a pipe-separated string ('Black|White'), an array, or a number. */
3920	+  selectedRefinements?: Record<string, string | number | (string | number)[] | undefined>;
3921	+};
3922	+
3923	+type UseFilterDrawerStateReturn = {
3924	+  /** The category currently pending selection in the drawer, or undefined if none. */
3925	+  pendingCategoryId: string | undefined;
3926	+  /** Replaces the pending category — use to set a new selection or clear (pass undefined). */
3927	+  setPendingCategoryId: (id: string | undefined) => void;
3928	+  pendingRefine: PendingRefinements;
3929	+  setValues: (attributeId: string, values: string[]) => void;
3930	+  removeValue: (attributeId: string, value: string) => void;
3931	+  clearAll: () => void;
3932	+  /** Re-derives pendingRefine from a (possibly different) selectedRefinements snapshot —
3933	+   *  same parsing the drawer-open resync uses. For a caller that reverts a pending category
3934	+   *  change back to the currently-applied category (e.g. removing the category chip): that
3935	+   *  category change already cleared pendingRefine via clearAll, so reverting it must also
3936	+   *  restore whatever refine is actually still applied, not leave the buffer empty. */
3937	+  resyncPendingRefine: (selectedRefinements?: UseFilterDrawerStateParams['selectedRefinements']) => void;
3938	+};
3939	+
3940	+/**
3941	+ * Parses a searchParams.refine-shaped object into the buffered PendingRefinements shape —
3942	+ * split out so both the drawer-open resync effect and a caller-triggered resync
3943	+ * (resyncPendingRefine) share one implementation.
3944	+ */
3945	+const parseSelectedRefinements = (
3946	+  selectedRefinements: UseFilterDrawerStateParams['selectedRefinements'],
3947	+): PendingRefinements => {
3948	+  const initial: PendingRefinements = {};
3949	+  Object.entries(selectedRefinements ?? {}).forEach(([attributeId, rawValue]) => {
3950	+    if (attributeId === 'cgid' || rawValue == null) return;
3951	+    // searchParams.refine values can be arrays (from buildAppliedRefine), pipe-separated
3952	+    // strings ('Black|White' — SFCC URL encoding), or plain numbers. Handle all three so
3953	+    // the resync works correctly regardless of whether the value was round-tripped through
3954	+    // the URL parser or set directly.
3955	+    const values: string[] = Array.isArray(rawValue) ? rawValue.map(String) : String(rawValue).split('|');
3956	+    if (values.length > 0 && values[0] !== '') initial[attributeId] = values;
3957	+  });
3958	+  return initial;
3959	+};
3960	+
3961	+/**
3962	+ * Buffers SFCC-847 filter-drawer selections (category + every refinement facet) in local
3963	+ * state instead of applying each click straight to the URL/product grid. Resyncs from the
3964	+ * page's currently-applied filters every time the drawer opens, so a value chosen and then
3965	+ * abandoned (drawer closed without pressing APPLY) never reaches the URL, and reopening
3966	+ * after a previous APPLY reflects reality rather than stale local state.
3967	+ *
3968	+ * @returns pending category/refinement selections plus mutators. The caller is responsible
3969	+ * for actually applying them (navigating) when the shopper presses APPLY.
3970	+ */
3971	+export const useFilterDrawerState = ({
3972	+  isOpen,
3973	+  categoryId,
3974	+  selectedRefinements,
3975	+}: UseFilterDrawerStateParams): UseFilterDrawerStateReturn => {
3976	+  const [pendingCategoryId, setPendingCategoryId] = useState<string | undefined>(categoryId);
3977	+  const [pendingRefine, setPendingRefine] = useState<PendingRefinements>({});
3978	+
