3980	+  // browser paints. This prevents the visible flash of stale checkbox state that useEffect
3981	+  // causes: with useEffect the drawer renders once with the previous pendingRefine (user
3982	+  // briefly sees wrong checked state), then the effect fires and corrects it. The filter
3983	+  // drawer is always closed during SSR so the isOpen guard means this body never runs
3984	+  // server-side — the layout-effect SSR warning does not apply here.
3985	+  useLayoutEffect(() => {
3986	+    if (!isOpen) return;
3987	+    setPendingRefine(parseSelectedRefinements(selectedRefinements));
3988	+    setPendingCategoryId(categoryId);
3989	+    // Resync is keyed on `isOpen` alone. `categoryId`/`selectedRefinements` change on every
3990	+    // navigation — including the one APPLY itself triggers — so including them here would
3991	+    // re-run this effect right after APPLY and stomp the just-applied selection straight
3992	+    // back to whatever the next render resolves it to.
3993	+  }, [isOpen]);
3994	+
3995	+  const resyncPendingRefine = (nextSelectedRefinements?: UseFilterDrawerStateParams['selectedRefinements']) => {
3996	+    setPendingRefine(parseSelectedRefinements(nextSelectedRefinements));
3997	+  };
3998	+
3999	+  const setValues = (attributeId: string, values: string[]) => {
4000	+    setPendingRefine((prev) => {
4001	+      if (values.length === 0) {
4002	+        const { [attributeId]: _removed, ...rest } = prev;
4003	+        return rest;
4004	+      }
4005	+      return { ...prev, [attributeId]: values };
4006	+    });
4007	+  };
4008	+
4009	+  const removeValue = (attributeId: string, value: string) => {
4010	+    setPendingRefine((prev) => {
4011	+      const next = (prev[attributeId] ?? []).filter((v) => v !== value);
4012	+      if (next.length === 0) {
4013	+        const { [attributeId]: _removed, ...rest } = prev;
4014	+        return rest;
4015	+      }
4016	+      return { ...prev, [attributeId]: next };
4017	+    });
4018	+  };
4019	+
4020	+  const clearAll = () => setPendingRefine({});
4021	+
4022	+  return {
4023	+    pendingCategoryId,
4024	+    setPendingCategoryId,
4025	+    pendingRefine,
4026	+    setValues,
4027	+    removeValue,
4028	+    clearAll,
4029	+    resyncPendingRefine,
4030	+  };
4031	+};
