4033	+export type AppliedRefine = Record<string, string | number | (string | number)[]>;
4034	+
4035	+/**
4036	+ * Merges buffered facet selections into the page's real `searchParams.refine` object —
4037	+ * the pure computation behind the drawer's APPLY handler, split out so it's testable
4038	+ * without a component or navigation. Every attribute this drawer manages (every non-cgid
4039	+ * attributeId SFCC currently returns as a refinement) is fully overwritten from
4040	+ * `pendingRefine` — including being deleted if the shopper unticked it back to empty —
4041	+ * while any attribute this drawer does not manage (e.g. StoreInventoryFilter's `ilids`) is
4042	+ * left exactly as it was in `currentRefine`.
4043	+ *
4044	+ * @returns a new refine object; never mutates `currentRefine`.
4045	+ */
4046	+export const buildAppliedRefine = (
4047	+  currentRefine: AppliedRefine,
4048	+  managedAttributeIds: string[],
4049	+  pendingRefine: PendingRefinements,
4050	+): AppliedRefine => {
4051	+  const nextRefine: AppliedRefine = { ...currentRefine };
4052	+  const managedSet = new Set(managedAttributeIds);
4053	+  managedSet.forEach((attributeId) => {
4054	+    delete nextRefine[attributeId];
4055	+  });
4056	+  // Only write back attributes this drawer manages — unmanaged ones (e.g. ilids) are already
4057	+  // preserved from the { ...currentRefine } spread above and must not be overwritten with the
4058	+  // array-converted form that parseSelectedRefinements produces.
4059	+  Object.entries(pendingRefine).forEach(([attributeId, values]) => {
4060	+    if (managedSet.has(attributeId)) {
4061	+      nextRefine[attributeId] = values;
4062	+    }
4063	+  });
4064	+  return nextRefine;
4065	+};
